function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const userText = "C++";
const literalPattern = new RegExp(escapeRegExp(userText), "i");

console.log(literalPattern.test("Learn C++ today")); // true
console.log(literalPattern.test("Learn C today"));   // false

